package schemactx

// QuerySyntax says what a query is for a driver whose dialect is not a
// language a model already knows: tobira's own JSON request shapes, a
// command document, a CLI command line. It reads as the end of the sentence
// "A query for this database is ...", with examples, so a model writes what
// the driver runs rather than what the dialect's name suggests (mongosh for
// MongoDB, say). A dialect with no entry, such as a SQL one, gets "".
func QuerySyntax(dialect string) string { return querySyntax[dialect] }

var querySyntax = map[string]string{
	"mongodb":        `one MongoDB database command document in JSON or extended JSON, never mongosh or JavaScript (no db.collection.find()). The first key names the command, key order is kept, and it runs in the current database. Examples: {"find":"orders","filter":{"status":"paid"},"sort":{"_id":-1},"limit":10} · {"aggregate":"orders","pipeline":[{"$match":{}},{"$count":"n"}],"cursor":{}} · {"count":"orders","query":{"status":"paid"}} · {"distinct":"orders","key":"status"}`,
	"redis":          `one Redis command as typed in redis-cli (double quotes take \n, \" and \xHH escapes, single quotes are literal). Examples: HGETALL user:1 · ZRANGE leaderboard 0 -1 WITHSCORES · SCAN 0 MATCH user:* COUNT 100 · FT.SEARCH idx "@age:[30 40]" LIMIT 0 50`,
	"elasticsearch":  `one JSON object: a search that names the "index" (a name, pattern or comma list) and gives the rest of a _search body, or a raw REST call with "method", "path" and an optional "body". Examples: {"index":"orders","query":{"term":{"status":"paid"}},"size":50} · {"index":"orders","size":0,"aggs":{"by_status":{"terms":{"field":"status"}}}} · {"method":"POST","path":"/orders/_count","body":{"query":{"match_all":{}}}}`,
	"firestore-json": `one JSON object describing a read, since Firestore has no query language: exactly one of "collection" (a path such as orders or users/ada/orders), "collectionGroup" (a collection id) or "document" (a path), with optional "where" (a list of [field, op, value] triples; op is ==, !=, <, <=, >, >=, array-contains, array-contains-any, in or not-in), "orderBy", "limit", "offset", "select" and "count": true. Examples: {"collection":"orders","where":[["status","==","paid"]],"orderBy":[["total","desc"]],"limit":20} · {"collection":"orders","count":true} · {"document":"users/ada"}`,
	"pinecone":       `one JSON object in Pinecone's own spelling with an "op" of query (the default), fetch, list or stats; "index" and "namespace" default to the connection's. Examples: {"namespace":"en","vector":[0.1,0.2,0.3],"topK":5,"filter":{"genre":{"$eq":"drama"}}} · {"op":"fetch","namespace":"en","ids":["doc-1","doc-2"]} · {"op":"list","namespace":"en","prefix":"doc-","limit":50} · {"op":"stats"}`,
	"qdrant":         `one JSON object with an "op" of scroll, search, query, count or retrieve, a "collection" and the rest of that gRPC request in the field names of Qdrant's proto files. Examples: {"op":"scroll","collection":"docs","filter":{"must":[{"field":{"key":"lang","match":{"keyword":"en"}}}]},"limit":20} · {"op":"count","collection":"docs"} · {"op":"search","collection":"docs","vector":[0.1,0.2,0.3],"limit":5} · {"op":"retrieve","collection":"docs","ids":[{"num":"42"}]}`,
	"milvus":         `one JSON object with a "collection" and an "op" of query, get, count or search; without an op, a "vector" or "text" searches, "ids" gets and anything else queries. Examples: {"collection":"docs","filter":"year >= 2020","outputFields":["title"],"limit":20} · {"op":"count","collection":"docs"} · {"op":"get","collection":"docs","ids":[42,43]} · {"collection":"docs","annsField":"embedding","vector":[0.1,0.2,0.3],"limit":5}`,
	"weaviate":       `one JSON request with a "collection" and optional "fields", "where", "sort", "limit", "offset" and at most one search (nearVector, nearObject, nearText, bm25 or hybrid), values written as in Weaviate's GraphQL arguments; or one raw GraphQL read. Examples: {"collection":"Article","fields":["title"],"where":{"path":["n"],"operator":"GreaterThan","valueInt":2},"limit":10} · {"collection":"Article","bm25":{"query":"database","properties":["title"]}}`,
	"chroma":         `one JSON object with a "collection" and an "op" of get, query or count; without an op, "queryEmbeddings" or "queryTexts" query and anything else gets. Examples: {"collection":"docs","where":{"year":{"$gte":2020}},"limit":20} · {"collection":"docs","queryTexts":["how do I search vectors?"],"nResults":5} · {"op":"count","collection":"docs"}`,
	"github":         `one JSON object with an "op" of list (the default), get, search, repositories, rest, graphql or rate_limit. list and get take a "collection" (in a repository: issues, pull_requests, issue_comments, commits, branches, tags, releases, labels, milestones, workflow_runs; in an owner namespace: repositories, issues, pull_requests, commits across its repositories) and an optional "repo" (owner/name or an owner; the namespace otherwise); list also takes the endpoint's own parameters (an owner's issues take "q" with search qualifiers, "sort" and "order") and a "limit" (default 100, at most 1000). Never SQL. Examples: {"collection":"issues","state":"open","labels":"bug","limit":50} · {"collection":"issues","repo":"acme","q":"label:bug","sort":"updated","order":"desc"} · {"op":"get","collection":"pull_requests","number":12} · {"op":"search","type":"issues","q":"repo:octo/widgets is:open label:bug","sort":"updated"} · {"op":"rest","path":"/repos/octo/widgets/topics"} · {"op":"graphql","query":"{ repository(owner:\"octo\", name:\"widgets\") { stargazerCount } }"} · {"op":"rate_limit"}`,
	"cosmos-sql":     `one Cosmos DB SQL SELECT; the container is the name after the top-level FROM. Examples: SELECT * FROM orders o WHERE o.status = 'paid' ORDER BY o.total DESC · SELECT VALUE COUNT(1) FROM orders`,
	"partiql":        `one DynamoDB PartiQL statement, with the table (and an index as "table"."index") in double quotes. Examples: SELECT * FROM "orders" WHERE customer = 'c-42' · SELECT id, status FROM "orders"."by_status" WHERE status = 'paid'`,
	"cypher":         `one Cypher statement. The collections in the schema context are node labels and their properties; relationship types are not listed, so when a question needs them run CALL db.relationshipTypes() or MATCH ()-[r]->() RETURN DISTINCT type(r). Positional parameters bind to $1, $2 … Examples: MATCH (p:Person) WHERE p.born < 1900 RETURN p.name ORDER BY p.born LIMIT 20 · MATCH (p:Person {name: 'Ada'})-[:KNOWS*1..2]-(q) RETURN DISTINCT q.name · MATCH (n:Order) RETURN count(n)`,
	"influxdb3-sql":  `one SQL statement for InfluxDB 3, where measurements are tables and "time" is the timestamp column. Examples: SELECT * FROM cpu WHERE time > now() - INTERVAL '1 hour' ORDER BY time DESC · SELECT date_bin(INTERVAL '5 minutes', time) AS t, avg(usage) FROM cpu GROUP BY t`,
}
